import { SynapseEnhancedHttpClient, SynapseEnhancedError } from "../utils/http.ts";
import { ErrorCode } from "../utils/error-codes.ts";
import { SynapseEnhancedClient, type ISynapseEnhancedConfig } from "../index.ts";
import type {
    IRegisterParams,
    IRegisterResponse,
    IUnifiedLoginParams,
    ILoginResponse,
    IRefreshParams,
    IRefreshResponse,
    IUserProfile,
    ICreateRoomParams,
    ICreateRoomResponse,
    IRoomInfo,
    IPublicRoomsParams,
    IPublicRoomsResponse,
    ISendMessageParams,
    IUnifiedSendEventResponse,
    IMessagesParams,
    IMessagesResponse,
    IEditMessageParams,
    IRedactParams,
    IRedactResponse,
    IUserRoomsResponse,
    IInviteParams,
    IJoinRoomParams,
    ILeaveRoomParams,
} from "./unified-client.types.ts";

function toRecord(obj: object): Record<string, unknown> {
    return obj as Record<string, unknown>;
}

export interface IUnifiedClientConfig extends ISynapseEnhancedConfig {
    baseUrl: string;
    accessToken: string;
}

/**
 * UnifiedMatrixClient - Unified Matrix client
 * Integrates standard Matrix Client API and Synapse enhanced features
 */
export class UnifiedMatrixClient {
    private readonly httpClient: SynapseEnhancedHttpClient;
    private readonly enhancedClient: SynapseEnhancedClient;
    private readonly basePath: string;

    /**
     * Authentication related operations
     */
    public readonly auth: {
        register: (params: IRegisterParams) => Promise<IRegisterResponse>;
        login: (params: IUnifiedLoginParams) => Promise<ILoginResponse>;
        logout: () => Promise<void>;
        logoutAll: () => Promise<void>;
        refreshToken: (params: IRefreshParams) => Promise<IRefreshResponse>;
    };

    /**
     * User account related operations
     */
    public readonly user: {
        whoami: () => Promise<{ user_id: string; device_id?: string }>;
        getProfile: (userId: string) => Promise<IUserProfile>;
        updateDisplayname: (userId: string, displayname: string) => Promise<void>;
        updateAvatar: (userId: string, avatarUrl: string) => Promise<void>;
        changePassword: (newPassword: string, auth?: Record<string, unknown>) => Promise<void>;
        deactivateAccount: (
            auth?: Record<string, unknown>,
            idServer?: string,
        ) => Promise<{ id_server_unbind_result: string }>;
    };

    /**
     * Room related operations
     */
    public readonly room: {
        createRoom: (params: ICreateRoomParams) => Promise<ICreateRoomResponse>;
        joinRoom: (roomId: string, params?: IJoinRoomParams) => Promise<{ room_id: string }>;
        leaveRoom: (roomId: string, params?: ILeaveRoomParams) => Promise<void>;
        inviteUser: (roomId: string, params: IInviteParams) => Promise<void>;
        kickUser: (roomId: string, userId: string, reason?: string) => Promise<void>;
        banUser: (roomId: string, userId: string, reason?: string) => Promise<void>;
        unbanUser: (roomId: string, userId: string) => Promise<void>;
        getRoomInfo: (roomId: string) => Promise<IRoomInfo>;
        deleteRoom: (roomId: string) => Promise<void>;
        getPublicRooms: (params?: IPublicRoomsParams) => Promise<IPublicRoomsResponse>;
        getUserRooms: (userId: string) => Promise<IUserRoomsResponse>;
    };

    /**
     * Message related operations
     */
    public readonly message: {
        sendMessage: (
            roomId: string,
            eventType: string,
            content: ISendMessageParams,
            txnId?: string,
        ) => Promise<IUnifiedSendEventResponse>;
        getMessages: (roomId: string, params: IMessagesParams) => Promise<IMessagesResponse>;
        editMessage: (
            roomId: string,
            eventId: string,
            eventType: string,
            params: IEditMessageParams,
            txnId?: string,
        ) => Promise<IUnifiedSendEventResponse>;
        replyMessage: (
            roomId: string,
            eventId: string,
            content: ISendMessageParams,
        ) => Promise<IUnifiedSendEventResponse>;
        redactEvent: (
            roomId: string,
            eventId: string,
            params?: IRedactParams,
            txnId?: string,
        ) => Promise<IRedactResponse>;
    };

    /**
     * Enhanced features client
     */
    public readonly enhanced: ReturnType<SynapseEnhancedClient["getEnhancedClient"]>;

    public constructor(config: IUnifiedClientConfig) {
        this.basePath = "/_matrix/client/v3";
        this.httpClient = new SynapseEnhancedHttpClient({
            baseUrl: config.baseUrl,
            accessToken: config.accessToken,
            apiPrefix: this.basePath,
            timeout: config.timeout,
        });

        this.enhancedClient = new SynapseEnhancedClient({
            baseUrl: config.baseUrl,
            accessToken: config.accessToken,
            apiPrefix: config.apiPrefix,
            timeout: config.timeout,
        });

        this.auth = {
            register: this.register.bind(this),
            login: this.login.bind(this),
            logout: this.logout.bind(this),
            logoutAll: this.logoutAll.bind(this),
            refreshToken: this.refreshToken.bind(this),
        };

        this.user = {
            whoami: this.whoami.bind(this),
            getProfile: this.getProfile.bind(this),
            updateDisplayname: this.updateDisplayname.bind(this),
            updateAvatar: this.updateAvatar.bind(this),
            changePassword: this.changePassword.bind(this),
            deactivateAccount: this.deactivateAccount.bind(this),
        };

        this.room = {
            createRoom: this.createRoom.bind(this),
            joinRoom: this.joinRoom.bind(this),
            leaveRoom: this.leaveRoom.bind(this),
            inviteUser: this.inviteUser.bind(this),
            kickUser: this.kickUser.bind(this),
            banUser: this.banUser.bind(this),
            unbanUser: this.unbanUser.bind(this),
            getRoomInfo: this.getRoomInfo.bind(this),
            deleteRoom: this.deleteRoom.bind(this),
            getPublicRooms: this.getPublicRooms.bind(this),
            getUserRooms: this.getUserRooms.bind(this),
        };

        this.message = {
            sendMessage: this.sendMessage.bind(this),
            getMessages: this.getMessages.bind(this),
            editMessage: this.editMessage.bind(this),
            replyMessage: this.replyMessage.bind(this),
            redactEvent: this.redactEvent.bind(this),
        };

        this.enhanced = this.enhancedClient.getEnhancedClient();
    }

    private async register(params: IRegisterParams): Promise<IRegisterResponse> {
        const response = await this.httpClient.post<IRegisterResponse>("/register", {
            username: params.username,
            password: params.password,
            auth: params.auth,
            device_id: params.device_id,
            initial_device_display_name: params.initial_device_display_name,
            inhibit_login: params.inhibit_login,
            admin: params.admin,
            displayname: params.displayname,
        });

        if (!response.data) {
            throw new SynapseEnhancedError("Registration failed", ErrorCode.UNKNOWN, undefined, 500);
        }

        return response.data;
    }

    private async login(params: IUnifiedLoginParams): Promise<ILoginResponse> {
        const response = await this.httpClient.post<ILoginResponse>("/login", {
            type: params.type,
            user: params.user,
            password: params.password,
            device_id: params.device_id,
            initial_device_display_name: params.initial_device_display_name,
        });

        if (!response.data) {
            throw new SynapseEnhancedError("Login failed", ErrorCode.UNKNOWN, undefined, 500);
        }

        return response.data;
    }

    private async logout(): Promise<void> {
        await this.httpClient.post("/logout");
    }

    private async logoutAll(): Promise<void> {
        await this.httpClient.post("/logout/all");
    }

    private async refreshToken(params: IRefreshParams): Promise<IRefreshResponse> {
        const response = await this.httpClient.post<IRefreshResponse>("/refresh", {
            refresh_token: params.refresh_token,
        });

        if (!response.data) {
            throw new SynapseEnhancedError("Token refresh failed", ErrorCode.UNKNOWN, undefined, 500);
        }

        return response.data;
    }

    private async whoami(): Promise<{ user_id: string; device_id?: string }> {
        const response = await this.httpClient.get<{ user_id: string; device_id?: string }>("/account/whoami");

        if (!response.data) {
            throw new SynapseEnhancedError("Failed to get user info", ErrorCode.UNKNOWN, undefined, 500);
        }

        return response.data;
    }

    private async getProfile(userId: string): Promise<IUserProfile> {
        const response = await this.httpClient.get<IUserProfile>(`/account/profile/${encodeURIComponent(userId)}`);

        if (!response.data) {
            throw new SynapseEnhancedError("Failed to get profile", ErrorCode.UNKNOWN, undefined, 500);
        }

        return response.data;
    }

    private async updateDisplayname(userId: string, displayname: string): Promise<void> {
        await this.httpClient.put(`/account/profile/${encodeURIComponent(userId)}/displayname`, {
            displayname,
        });
    }

    private async updateAvatar(userId: string, avatarUrl: string): Promise<void> {
        await this.httpClient.put(`/account/profile/${encodeURIComponent(userId)}/avatar_url`, {
            avatar_url: avatarUrl,
        });
    }

    private async changePassword(newPassword: string, auth?: Record<string, unknown>): Promise<void> {
        await this.httpClient.post("/account/password", {
            new_password: newPassword,
            auth,
        });
    }

    private async deactivateAccount(
        auth?: Record<string, unknown>,
        idServer?: string,
    ): Promise<{ id_server_unbind_result: string }> {
        const response = await this.httpClient.post<{ id_server_unbind_result: string }>("/account/deactivate", {
            auth,
            id_server: idServer,
        });

        if (!response.data) {
            throw new SynapseEnhancedError("Account deactivation failed", ErrorCode.UNKNOWN, undefined, 500);
        }

        return response.data;
    }

    private async createRoom(params: ICreateRoomParams): Promise<ICreateRoomResponse> {
        const response = await this.httpClient.post<ICreateRoomResponse>("/createRoom", {
            preset: params.preset,
            room_alias_name: params.room_alias_name,
            name: params.name,
            topic: params.topic,
            invite: params.invite,
            invite_3pid: params.invite_3pid,
            creation_content: params.creation_content,
            initial_state: params.initial_state,
            room_version: params.room_version,
        });

        if (!response.data) {
            throw new SynapseEnhancedError("Failed to create room", ErrorCode.UNKNOWN, undefined, 500);
        }

        return response.data;
    }

    private async joinRoom(roomId: string, params?: IJoinRoomParams): Promise<{ room_id: string }> {
        const response = await this.httpClient.post<{ room_id: string }>(
            `/rooms/${encodeURIComponent(roomId)}/join`,
            params ? toRecord(params) : undefined,
        );

        if (!response.data) {
            throw new SynapseEnhancedError("Failed to join room", ErrorCode.UNKNOWN, undefined, 500);
        }

        return response.data;
    }

    private async leaveRoom(roomId: string, params?: ILeaveRoomParams): Promise<void> {
        await this.httpClient.post(`/rooms/${encodeURIComponent(roomId)}/leave`, params ? toRecord(params) : undefined);
    }

    private async inviteUser(roomId: string, params: IInviteParams): Promise<void> {
        await this.httpClient.post(`/rooms/${encodeURIComponent(roomId)}/invite`, {
            user_id: params.user_id,
            reason: params.reason,
        });
    }

    private async kickUser(roomId: string, userId: string, reason?: string): Promise<void> {
        await this.httpClient.post(`/rooms/${encodeURIComponent(roomId)}/kick`, {
            user_id: userId,
            reason,
        });
    }

    private async banUser(roomId: string, userId: string, reason?: string): Promise<void> {
        await this.httpClient.post(`/rooms/${encodeURIComponent(roomId)}/ban`, {
            user_id: userId,
            reason,
        });
    }

    private async unbanUser(roomId: string, userId: string): Promise<void> {
        await this.httpClient.post(`/rooms/${encodeURIComponent(roomId)}/unban`, {
            user_id: userId,
        });
    }

    private async getRoomInfo(roomId: string): Promise<IRoomInfo> {
        const response = await this.httpClient.get<IRoomInfo>(`/directory/room/${encodeURIComponent(roomId)}`);

        if (!response.data) {
            throw new SynapseEnhancedError("Failed to get room info", ErrorCode.UNKNOWN, undefined, 500);
        }

        return response.data;
    }

    private async deleteRoom(roomId: string): Promise<void> {
        await this.httpClient.delete(`/directory/room/${encodeURIComponent(roomId)}`);
    }

    private async getPublicRooms(params?: IPublicRoomsParams): Promise<IPublicRoomsResponse> {
        const queryParams: Record<string, string> = {};

        if (params?.limit) queryParams.limit = params.limit.toString();
        if (params?.since) queryParams.since = params.since;
        if (params?.server) queryParams.server = params.server;
        if (params?.search_term) queryParams.search_term = params.search_term;

        const response = await this.httpClient.get<IPublicRoomsResponse>("/publicRooms", queryParams);

        if (!response.data) {
            throw new SynapseEnhancedError("Failed to get public rooms", ErrorCode.UNKNOWN, undefined, 500);
        }

        return response.data;
    }

    private async getUserRooms(userId: string): Promise<IUserRoomsResponse> {
        const response = await this.httpClient.get<IUserRoomsResponse>(`/user/${encodeURIComponent(userId)}/rooms`);

        if (!response.data) {
            throw new SynapseEnhancedError("Failed to get user rooms", ErrorCode.UNKNOWN, undefined, 500);
        }

        return response.data;
    }

    private async sendMessage(
        roomId: string,
        eventType: string,
        content: ISendMessageParams,
        txnId?: string,
    ): Promise<IUnifiedSendEventResponse> {
        const transactionId = txnId || this.generateTransactionId();
        const response = await this.httpClient.post<IUnifiedSendEventResponse>(
            `/rooms/${encodeURIComponent(roomId)}/send/${encodeURIComponent(eventType)}/${transactionId}`,
            toRecord(content),
        );

        if (!response.data) {
            throw new SynapseEnhancedError("Failed to send message", ErrorCode.UNKNOWN, undefined, 500);
        }

        return response.data;
    }

    private async getMessages(roomId: string, params: IMessagesParams): Promise<IMessagesResponse> {
        const queryParams: Record<string, string> = {
            from: params.from,
            dir: params.dir,
        };

        if (params.limit) queryParams.limit = params.limit.toString();
        if (params.to) queryParams.to = params.to;
        if (params.filter) queryParams.filter = params.filter;

        const response = await this.httpClient.get<IMessagesResponse>(
            `/rooms/${encodeURIComponent(roomId)}/messages`,
            queryParams,
        );

        if (!response.data) {
            throw new SynapseEnhancedError("Failed to get messages", ErrorCode.UNKNOWN, undefined, 500);
        }

        return response.data;
    }

    private async editMessage(
        roomId: string,
        _eventId: string,
        eventType: string,
        params: IEditMessageParams,
        txnId?: string,
    ): Promise<IUnifiedSendEventResponse> {
        const transactionId = txnId || this.generateTransactionId();
        const response = await this.httpClient.put<IUnifiedSendEventResponse>(
            `/rooms/${encodeURIComponent(roomId)}/send/${encodeURIComponent(eventType)}/${transactionId}`,
            {
                "body": params.body,
                "msgtype": params.msgtype,
                "m.new_content": params["m.new_content"],
                "m.relates_to": params["m.relates_to"],
            },
        );

        if (!response.data) {
            throw new SynapseEnhancedError("Failed to edit message", ErrorCode.UNKNOWN, undefined, 500);
        }

        return response.data;
    }

    private async replyMessage(
        roomId: string,
        eventId: string,
        content: ISendMessageParams,
    ): Promise<IUnifiedSendEventResponse> {
        const response = await this.httpClient.post<IUnifiedSendEventResponse>(
            `/rooms/${encodeURIComponent(roomId)}/send/m.room.message`,
            {
                "msgtype": content.msgtype,
                "body": content.body,
                "m.relates_to": {
                    rel_type: "m.reply",
                    event_id: eventId,
                },
            },
        );

        if (!response.data) {
            throw new SynapseEnhancedError("Failed to reply to message", ErrorCode.UNKNOWN, undefined, 500);
        }

        return response.data;
    }

    private async redactEvent(
        roomId: string,
        eventId: string,
        params?: IRedactParams,
        txnId?: string,
    ): Promise<IRedactResponse> {
        const transactionId = txnId || this.generateTransactionId();
        const response = await this.httpClient.put<IRedactResponse>(
            `/rooms/${encodeURIComponent(roomId)}/redact/${encodeURIComponent(eventId)}/${transactionId}`,
            params ? toRecord(params) : undefined,
        );

        if (!response.data) {
            throw new SynapseEnhancedError("Failed to redact event", ErrorCode.UNKNOWN, undefined, 500);
        }

        return response.data;
    }

    private generateTransactionId(): string {
        return `m${Date.now()}${Math.random().toString(36).substring(2, 10)}`;
    }

    public getEnhancedClient(): SynapseEnhancedClient {
        return this.enhancedClient;
    }

    public getHttpClient(): SynapseEnhancedHttpClient {
        return this.httpClient;
    }
}
